            Class<?> varArgParameterType = methodParameterTypes[fixedParamLength].getComponentType();
            if (varArgParameterType == null) {
                return false; // Component type should not be null for varargs
            }
            for (int i = fixedParamLength; i < parameterTypes.length; i++) {
                if (!ClassUtils.isAssignable(parameterTypes[i], varArgParameterType, true)) {
                    return false;
                }
            }
        }

        return true;
    } else {
        // Regular non-varargs method
        return ClassUtils.isAssignable(parameterTypes, methodParameterTypes, true);
    }
}

